import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        x = int(sys.stdin.readline())
        found = False
        for a in range(1, 1 << 30):
            b = x ^ a
            if b > 0 and (a + b) % 2 == 0 and (a + b) // 2 == x:
                print(a, b)
                found = True
                break
        if not found:
            print(-1)

solve()
